class Solution {
  public int smallestBalancedIndex(int[] nums) {
    int n = nums.length;
    long CAP = 1_000_000_000_000_000L;
    long[] suffix = new long[n + 1];
    suffix[n] = 1;
    for (int i = n - 1; i >= 0; i--)
      suffix[i] = suffix[i + 1] > CAP / nums[i] ? CAP : Math.min(CAP, suffix[i + 1] * nums[i]);
    long left = 0;
    for (int i = 0; i < n; i++) {
      if (left == suffix[i + 1] && suffix[i + 1] < CAP) return i;
      left += nums[i];
    }
    return -1;
  }
}
